    17	import { MatrixClient } from "matrix-js-sdk/src/matrix";
    18	import { createContext } from "react";
    19	
    20	import defaultDispatcher from "../dispatcher/dispatcher";
    21	import LegacyCallHandler from "../LegacyCallHandler";
    22	import { PosthogAnalytics } from "../PosthogAnalytics";
    23	import { SlidingSyncManager } from "../SlidingSyncManager";
    24	import { AccountPasswordStore } from "../stores/AccountPasswordStore";
    25	import { MemberListStore } from "../stores/MemberListStore";
    26	import { RoomNotificationStateStore } from "../stores/notifications/RoomNotificationStateStore";
    27	import RightPanelStore from "../stores/right-panel/RightPanelStore";
    28	import { RoomViewStore } from "../stores/RoomViewStore";
    29	import SpaceStore, { SpaceStoreClass } from "../stores/spaces/SpaceStore";
    30	import TypingStore from "../stores/TypingStore";
    31	import { WidgetLayoutStore } from "../stores/widgets/WidgetLayoutStore";
    32	import { WidgetPermissionStore } from "../stores/widgets/WidgetPermissionStore";
    33	import WidgetStore from "../stores/WidgetStore";
    34	import {
    35	    VoiceBroadcastPlaybacksStore,
    36	    VoiceBroadcastPreRecordingStore,
    37	    VoiceBroadcastRecordingsStore,
    38	} from "../voice-broadcast";
    39	
    40	export const SDKContext = createContext<SdkContextClass>(undefined);
    41	SDKContext.displayName = "SDKContext";
    42	
    43	/**
    44	 * A class which lazily initialises stores as and when they are requested, ensuring they remain
    45	 * as singletons scoped to this object.
    46	 */
    47	export class SdkContextClass {
    48	    /**
    49	     * The global SdkContextClass instance. This is a temporary measure whilst so many stores remain global
    50	     * as well. Over time, these stores should accept a `SdkContextClass` instance in their constructor.
    51	     * When all stores do this, this static variable can be deleted.
    52	     */
    53	    public static readonly instance = new SdkContextClass();
    54	
    55	    // Optional as we don't have a client on initial load if unregistered. This should be set
    56	    // when the MatrixClient is first acquired in the dispatcher event Action.OnLoggedIn.
    57	    // It is only safe to set this once, as updating this value will NOT notify components using
    58	    // this Context.
    59	    public client?: MatrixClient;
    60	
    61	    // All protected fields to make it easier to derive test stores
    62	    protected _WidgetPermissionStore?: WidgetPermissionStore;
    63	    protected _MemberListStore?: MemberListStore;
    64	    protected _RightPanelStore?: RightPanelStore;
    65	    protected _RoomNotificationStateStore?: RoomNotificationStateStore;
    66	    protected _RoomViewStore?: RoomViewStore;
    67	    protected _WidgetLayoutStore?: WidgetLayoutStore;
    68	    protected _WidgetStore?: WidgetStore;
    69	    protected _PosthogAnalytics?: PosthogAnalytics;
    70	    protected _SlidingSyncManager?: SlidingSyncManager;
    71	    protected _SpaceStore?: SpaceStoreClass;
    72	    protected _LegacyCallHandler?: LegacyCallHandler;
    73	    protected _TypingStore?: TypingStore;
    74	    protected _VoiceBroadcastRecordingsStore?: VoiceBroadcastRecordingsStore;
    75	    protected _VoiceBroadcastPreRecordingStore?: VoiceBroadcastPreRecordingStore;
    76	    protected _VoiceBroadcastPlaybacksStore?: VoiceBroadcastPlaybacksStore;
    77	    protected _AccountPasswordStore?: AccountPasswordStore;
    78	
    79	    /**
    80	     * Automatically construct stores which need to be created eagerly so they can register with
    81	     * the dispatcher.
    82	     */
    83	    public constructEagerStores(): void {
    84	        this._RoomViewStore = this.roomViewStore;
    85	    }
    86	
    87	    public get legacyCallHandler(): LegacyCallHandler {
    88	        if (!this._LegacyCallHandler) {
    89	            this._LegacyCallHandler = LegacyCallHandler.instance;
    90	        }
    91	        return this._LegacyCallHandler;
    92	    }
    93	    public get rightPanelStore(): RightPanelStore {
    94	        if (!this._RightPanelStore) {
    95	            this._RightPanelStore = RightPanelStore.instance;
    96	        }
    97	        return this._RightPanelStore;
    98	    }
    99	    public get roomNotificationStateStore(): RoomNotificationStateStore {
   100	        if (!this._RoomNotificationStateStore) {
   101	            this._RoomNotificationStateStore = RoomNotificationStateStore.instance;
   102	        }
   103	        return this._RoomNotificationStateStore;
   104	    }
   105	    public get roomViewStore(): RoomViewStore {
   106	        if (!this._RoomViewStore) {
   107	            this._RoomViewStore = new RoomViewStore(defaultDispatcher, this);
   108	        }
   109	        return this._RoomViewStore;
   110	    }
   111	    public get widgetLayoutStore(): WidgetLayoutStore {
   112	        if (!this._WidgetLayoutStore) {
   113	            this._WidgetLayoutStore = WidgetLayoutStore.instance;
   114	        }
   115	        return this._WidgetLayoutStore;
   116	    }
   117	    public get widgetPermissionStore(): WidgetPermissionStore {
   118	        if (!this._WidgetPermissionStore) {
   119	            this._WidgetPermissionStore = new WidgetPermissionStore(this);
   120	        }
   121	        return this._WidgetPermissionStore;
   122	    }
   123	    public get widgetStore(): WidgetStore {
   124	        if (!this._WidgetStore) {
   125	            this._WidgetStore = WidgetStore.instance;
   126	        }
   127	        return this._WidgetStore;
   128	    }
   129	    public get posthogAnalytics(): PosthogAnalytics {
   130	        if (!this._PosthogAnalytics) {
   131	            this._PosthogAnalytics = PosthogAnalytics.instance;
   132	        }
   133	        return this._PosthogAnalytics;
   134	    }
   135	    public get memberListStore(): MemberListStore {
   136	        if (!this._MemberListStore) {
   137	            this._MemberListStore = new MemberListStore(this);
   138	        }
   139	        return this._MemberListStore;
   140	    }
   141	    public get slidingSyncManager(): SlidingSyncManager {
   142	        if (!this._SlidingSyncManager) {
   143	            this._SlidingSyncManager = SlidingSyncManager.instance;
   144	        }
   145	        return this._SlidingSyncManager;
   146	    }
   147	    public get spaceStore(): SpaceStoreClass {
   148	        if (!this._SpaceStore) {
   149	            this._SpaceStore = SpaceStore.instance;
   150	        }
   151	        return this._SpaceStore;
   152	    }
   153	    public get typingStore(): TypingStore {
   154	        if (!this._TypingStore) {
   155	            this._TypingStore = new TypingStore(this);
   156	            window.mxTypingStore = this._TypingStore;
   157	        }
   158	        return this._TypingStore;
   159	    }
   160	
   161	    public get voiceBroadcastRecordingsStore(): VoiceBroadcastRecordingsStore {
   162	        if (!this._VoiceBroadcastRecordingsStore) {
   163	            this._VoiceBroadcastRecordingsStore = new VoiceBroadcastRecordingsStore();
   164	        }
   165	        return this._VoiceBroadcastRecordingsStore;
   166	    }
   167	
   168	    public get voiceBroadcastPreRecordingStore(): VoiceBroadcastPreRecordingStore {
   169	        if (!this._VoiceBroadcastPreRecordingStore) {
   170	            this._VoiceBroadcastPreRecordingStore = new VoiceBroadcastPreRecordingStore();
   171	        }
   172	        return this._VoiceBroadcastPreRecordingStore;
   173	    }
   174	
   175	    public get voiceBroadcastPlaybacksStore(): VoiceBroadcastPlaybacksStore {
   176	        if (!this._VoiceBroadcastPlaybacksStore) {
   177	            this._VoiceBroadcastPlaybacksStore = new VoiceBroadcastPlaybacksStore(this.voiceBroadcastRecordingsStore);
   178	        }
   179	        return this._VoiceBroadcastPlaybacksStore;
   180	    }
   181	
   182	    public get accountPasswordStore(): AccountPasswordStore {
   183	        if (!this._AccountPasswordStore) {
   184	            this._AccountPasswordStore = new AccountPasswordStore();
   185	        }
   186	        return this._AccountPasswordStore;
   187	    }
   188	}
"
