    16	
    17	import React, { ReactElement, useState } from "react";
    18	import classNames from "classnames";
    19	import { Room } from "matrix-js-sdk/src/models/room";
    20	import { RoomMember } from "matrix-js-sdk/src/matrix";
    21	
    22	import { MatrixClientPeg } from "../../../MatrixClientPeg";
    23	import MatrixClientContext from "../../../contexts/MatrixClientContext";
    24	import Tooltip, { Alignment } from "../elements/Tooltip";
    25	import { usePermalink } from "../../../hooks/usePermalink";
    26	import RoomAvatar from "../avatars/RoomAvatar";
    27	import MemberAvatar from "../avatars/MemberAvatar";
    28	import { _t } from "../../../languageHandler";
    29	import { Icon as LinkIcon } from "../../../../res/img/element-icons/room/composer/link.svg";
    30	import { Icon as UserIcon } from "../../../../res/img/compound/user.svg";
    31	
    32	export enum PillType {
    33	    UserMention = "TYPE_USER_MENTION",
    34	    RoomMention = "TYPE_ROOM_MENTION",
    35	    AtRoomMention = "TYPE_AT_ROOM_MENTION", // '@room' mention
    36	    EventInSameRoom = "TYPE_EVENT_IN_SAME_ROOM",
    37	    EventInOtherRoom = "TYPE_EVENT_IN_OTHER_ROOM",
    38	}
    39	
    40	export const pillRoomNotifPos = (text: string): number => {
    41	    return text.indexOf("@room");
    42	};
    43	
    44	export const pillRoomNotifLen = (): number => {
    45	    return "@room".length;
    46	};
    47	
    48	const linkIcon = <LinkIcon className="mx_Pill_LinkIcon mx_BaseAvatar mx_BaseAvatar_image" />;
    49	
    50	const PillRoomAvatar: React.FC<{
    51	    shouldShowPillAvatar: boolean;
    52	    room: Room | null;
    53	}> = ({ shouldShowPillAvatar, room }) => {
    54	    if (!shouldShowPillAvatar) {
    55	        return null;
    56	    }
    57	
    58	    if (room) {
    59	        return <RoomAvatar room={room} width={16} height={16} aria-hidden="true" />;
    60	    }
    61	    return linkIcon;
    62	};
    63	
    64	const PillMemberAvatar: React.FC<{
    65	    shouldShowPillAvatar: boolean;
    66	    member: RoomMember | null;
    67	}> = ({ shouldShowPillAvatar, member }) => {
    68	    if (!shouldShowPillAvatar) {
    69	        return null;
    70	    }
    71	
    72	    if (member) {
    73	        return <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle />;
    74	    }
    75	    return <UserIcon className="mx_Pill_UserIcon mx_BaseAvatar mx_BaseAvatar_image" />;
    76	};
    77	
    78	export interface PillProps {
    79	    // The Type of this Pill. If url is given, this is auto-detected.
    80	    type?: PillType;
    81	    // The URL to pillify (no validation is done)
    82	    url?: string;
    83	    /** Whether the pill is in a message. It will act as a link then. */
    84	    inMessage?: boolean;
    85	    // The room in which this pill is being rendered
    86	    room?: Room;
    87	    // Whether to include an avatar in the pill
    88	    shouldShowPillAvatar?: boolean;
    89	}
    90	
    91	export const Pill: React.FC<PillProps> = ({ type: propType, url, inMessage, room, shouldShowPillAvatar = true }) => {
    92	    const [hover, setHover] = useState(false);
    93	    const { event, member, onClick, resourceId, targetRoom, text, type } = usePermalink({
    94	        room,
    95	        type: propType,
    96	        url,
    97	    });
    98	
    99	    if (!type || !text) {
   100	        return null;
   101	    }
   102	
   103	    const classes = classNames("mx_Pill", {
   104	        mx_AtRoomPill: type === PillType.AtRoomMention,
   105	        mx_RoomPill: type === PillType.RoomMention,
   106	        mx_SpacePill: type === "space",
   107	        mx_UserPill: type === PillType.UserMention,
   108	        mx_UserPill_me: resourceId === MatrixClientPeg.get().getUserId(),
   109	        mx_EventPill: type === PillType.EventInOtherRoom || type === PillType.EventInSameRoom,
   110	    });
   111	
   112	    const onMouseOver = (): void => {
   113	        setHover(true);
   114	    };
   115	
   116	    const onMouseLeave = (): void => {
   117	        setHover(false);
   118	    };
   119	
   120	    const tip = hover && resourceId ? <Tooltip label={resourceId} alignment={Alignment.Right} /> : null;
   121	    let avatar: ReactElement | null = null;
   122	    let pillText: string | null = text;
   123	
   124	    switch (type) {
   125	        case PillType.EventInOtherRoom:
   126	            {
   127	                avatar = <PillRoomAvatar shouldShowPillAvatar={shouldShowPillAvatar} room={targetRoom} />;
   128	                pillText = _t("Message in %(room)s", {
   129	                    room: text,
   130	                });
   131	            }
   132	            break;
   133	        case PillType.EventInSameRoom:
   134	            {
   135	                if (event) {
   136	                    avatar = <PillMemberAvatar shouldShowPillAvatar={shouldShowPillAvatar} member={member} />;
   137	                    pillText = _t("Message from %(user)s", {
   138	                        user: text,
   139	                    });
   140	                } else {
   141	                    avatar = linkIcon;
   142	                    pillText = _t("Message");
   143	                }
   144	            }
   145	            break;
   146	        case PillType.AtRoomMention:
   147	        case PillType.RoomMention:
   148	        case "space":
   149	            avatar = <PillRoomAvatar shouldShowPillAvatar={shouldShowPillAvatar} room={targetRoom} />;
   150	            break;
   151	        case PillType.UserMention:
   152	            avatar = <PillMemberAvatar shouldShowPillAvatar={shouldShowPillAvatar} member={member} />;
   153	            break;
   154	        default:
   155	            return null;
   156	    }
   157	
   158	    return (
   159	        <bdi>
   160	            <MatrixClientContext.Provider value={MatrixClientPeg.get()}>
   161	                {inMessage && url ? (
   162	                    <a
   163	                        className={classes}
   164	                        href={url}
   165	                        onClick={onClick}
   166	                        onMouseOver={onMouseOver}
   167	                        onMouseLeave={onMouseLeave}
   168	                    >
   169	                        {avatar}
   170	                        <span className="mx_Pill_text">{pillText}</span>
   171	                        {tip}
   172	                    </a>
   173	                ) : (
   174	                    <span className={classes} onMouseOver={onMouseOver} onMouseLeave={onMouseLeave}>
   175	                        {avatar}
   176	                        <span className="mx_Pill_text">{pillText}</span>
   177	                        {tip}
   178	                    </span>
   179	                )}
   180	            </MatrixClientContext.Provider>
   181	        </bdi>
   182	    );
   183	};
"
}

