    16	
    17	import React from "react";
    18	import ReactDOM from "react-dom";
    19	import { PushProcessor } from "matrix-js-sdk/src/pushprocessor";
    20	import { MatrixEvent } from "matrix-js-sdk/src/models/event";
    21	
    22	import { MatrixClientPeg } from "../MatrixClientPeg";
    23	import SettingsStore from "../settings/SettingsStore";
    24	import { Pill, PillType, pillRoomNotifLen, pillRoomNotifPos } from "../components/views/elements/Pill";
    25	import { parsePermalink } from "./permalinks/Permalinks";
    26	import { PermalinkParts } from "./permalinks/PermalinkConstructor";
    27	
    28	/**
    29	 * A node here is an A element with a href attribute tag.
    30	 *
    31	 * It should be pillified if the permalink parser returns a result and one of the following conditions match:
    32	 * - Text content equals href. This is the case when sending a plain permalink inside a message.
    33	 * - The link does not have the "linkified" class.
    34	 *   Composer completions already create an A tag.
    35	 *   Linkify will not linkify things again. → There won't be a "linkified" class.
    36	 */
    37	const shouldBePillified = (node: Element, href: string, parts: PermalinkParts | null): boolean => {
    38	    // permalink parser didn't return any parts
    39	    if (!parts) return false;
    40	
    41	    const textContent = node.textContent;
    42	
    43	    // event permalink with custom label
    44	    if (parts.eventId && href !== textContent) return false;
    45	
    46	    return href === textContent || !node.classList.contains("linkified");
    47	};
    48	
    49	/**
    50	 * Recurses depth-first through a DOM tree, converting matrix.to links
    51	 * into pills based on the context of a given room.  Returns a list of
    52	 * the resulting React nodes so they can be unmounted rather than leaking.
    53	 *
    54	 * @param {Element[]} nodes - a list of sibling DOM nodes to traverse to try
    55	 *   to turn into pills.
    56	 * @param {MatrixEvent} mxEvent - the matrix event which the DOM nodes are
    57	 *   part of representing.
    58	 * @param {Element[]} pills: an accumulator of the DOM nodes which contain
    59	 *   React components which have been mounted as part of this.
    60	 *   The initial caller should pass in an empty array to seed the accumulator.
    61	 */
    62	export function pillifyLinks(nodes: ArrayLike<Element>, mxEvent: MatrixEvent, pills: Element[]): void {
    63	    const room = MatrixClientPeg.get().getRoom(mxEvent.getRoomId()) ?? undefined;
    64	    const shouldShowPillAvatar = SettingsStore.getValue("Pill.shouldShowPillAvatar");
    65	    let node = nodes[0];
    66	    while (node) {
    67	        let pillified = false;
    68	
    69	        if (node.tagName === "PRE" || node.tagName === "CODE" || pills.includes(node)) {
    70	            // Skip code blocks and existing pills
    71	            node = node.nextSibling as Element;
    72	            continue;
    73	        } else if (node.tagName === "A" && node.getAttribute("href")) {
    74	            const href = node.getAttribute("href")!;
    75	            const parts = parsePermalink(href);
    76	
    77	            if (shouldBePillified(node, href, parts)) {
    78	                const pillContainer = document.createElement("span");
    79	
    80	                const pill = (
    81	                    <Pill url={href} inMessage={true} room={room} shouldShowPillAvatar={shouldShowPillAvatar} />
    82	                );
    83	
    84	                ReactDOM.render(pill, pillContainer);
    85	                node.parentNode.replaceChild(pillContainer, node);
    86	                pills.push(pillContainer);
    87	                // Pills within pills aren't going to go well, so move on
    88	                pillified = true;
    89	
    90	                // update the current node with one that's now taken its place
    91	                node = pillContainer;
    92	            }
    93	        } else if (
    94	            node.nodeType === Node.TEXT_NODE &&
    95	            // as applying pills happens outside of react, make sure we're not doubly
    96	            // applying @room pills here, as a rerender with the same content won't touch the DOM
    97	            // to clear the pills from the last run of pillifyLinks
    98	            !node.parentElement.classList.contains("mx_AtRoomPill")
    99	        ) {
   100	            let currentTextNode = node as Node as Text | null;
   101	            const roomNotifTextNodes = [];
   102	
   103	            // Take a textNode and break it up to make all the instances of @room their
   104	            // own textNode, adding those nodes to roomNotifTextNodes
   105	            while (currentTextNode !== null) {
   106	                const roomNotifPos = pillRoomNotifPos(currentTextNode.textContent);
   107	                let nextTextNode: Text | null = null;
   108	                if (roomNotifPos > -1) {
   109	                    let roomTextNode = currentTextNode;
   110	
   111	                    if (roomNotifPos > 0) roomTextNode = roomTextNode.splitText(roomNotifPos);
   112	                    if (roomTextNode.textContent.length > pillRoomNotifLen()) {
   113	                        nextTextNode = roomTextNode.splitText(pillRoomNotifLen());
   114	                    }
   115	                    roomNotifTextNodes.push(roomTextNode);
   116	                }
   117	                currentTextNode = nextTextNode;
   118	            }
   119	
   120	            if (roomNotifTextNodes.length > 0) {
   121	                const pushProcessor = new PushProcessor(MatrixClientPeg.get());
   122	                const atRoomRule = pushProcessor.getPushRuleById(".m.rule.roomnotif");
   123	                if (atRoomRule && pushProcessor.ruleMatchesEvent(atRoomRule, mxEvent)) {
   124	                    // Now replace all those nodes with Pills
   125	                    for (const roomNotifTextNode of roomNotifTextNodes) {
   126	                        // Set the next node to be processed to the one after the node
   127	                        // we're adding now, since we've just inserted nodes into the structure
   128	                        // we're iterating over.
   129	                        // Note we've checked roomNotifTextNodes.length > 0 so we'll do this at least once
   130	                        node = roomNotifTextNode.nextSibling as Element;
   131	
   132	                        const pillContainer = document.createElement("span");
   133	                        const pill = (
   134	                            <Pill
   135	                                type={PillType.AtRoomMention}
   136	                                inMessage={true}
   137	                                room={room}
   138	                                shouldShowPillAvatar={shouldShowPillAvatar}
   139	                            />
   140	                        );
   141	
   142	                        ReactDOM.render(pill, pillContainer);
   143	                        roomNotifTextNode.parentNode.replaceChild(pillContainer, roomNotifTextNode);
   144	                        pills.push(pillContainer);
   145	                    }
   146	                    // Nothing else to do for a text node (and we don't need to advance
   147	                    // the loop pointer because we did it above)
   148	                    continue;
   149	                }
   150	            }
   151	        }
   152	
   153	        if (node.childNodes && node.childNodes.length && !pillified) {
   154	            pillifyLinks(node.childNodes as NodeListOf<Element>, mxEvent, pills);
   155	        }
   156	
   157	        node = node.nextSibling as Element;
   158	    }
   159	}
   160	
   161	/**
   162	 * Unmount all the pill containers from React created by pillifyLinks.
   163	 *
   164	 * It's critical to call this after pillifyLinks, otherwise
   165	 * Pills will leak, leaking entire DOM trees via the event
   166	 * emitter on BaseAvatar as per
   167	 * https://github.com/vector-im/element-web/issues/12417
   168	 *
   169	 * @param {Element[]} pills - array of pill containers whose React
   170	 *   components should be unmounted.
   171	 */
   172	export function unmountPills(pills: Element[]): void {
   173	    for (const pillContainer of pills) {
   174	        ReactDOM.unmountComponentAtNode(pillContainer);
   175	    }
   176	}
"
}

