    52	     * Should be used for click actions on the permalink.
    53	     * In case of a user permalink, a view profile action is dispatched.
    54	     */
    55	    onClick: (e: ButtonEvent) => void;
    56	    /**
    57	     * This can be for instance a user or room Id.
    58	     * null here means that the resource cannot be detected. Most likely if the URL was not a permalink.
    59	     */
    60	    resourceId: string | null;
    61	    /**
    62	     * Target room of the permalink:
    63	     * For an @room mention, this is the room where the permalink should be displayed.
    64	     * For a room permalink, it is the room from the permalink.
    65	     * null for other links or if the room cannot be found.
    66	     */
    67	    targetRoom: Room | null;
    68	    /**
    69	     * Type of the pill plus "space" for spaces.
    70	     * null here means that the type cannot be detected. Most likely if the URL was not a permalink.
    71	     */
    72	    type: PillType | "space" | null;
    73	    /**
    74	     * Target event of the permalink.
    75	     * Null if unable to load the event.
    76	     */
