    80	/**
    81	 * Tries to determine the pill type.
    82	 *
    83	 * If forcedType is present it will be returned.
    84	 * If the parse result contains a room Id or alias and an event Id:
    85	 * - Type is EventInSameRoom if the permalink room Id or alias equals the parsed room Id or alias
    86	 * - Type is EventInOtherRoom if the permalink room Id or alias not equals the parsed room Id or alias
    87	 * If the parse result contains a primary entity Id it will try to detect the type from it.
    88	 * Otherwise returns null.
    89	 *
    90	 * @param forcedType - Forced pill type. Will be used if present and short-circuits all othe conditions.
    91	 * @param parseResult - Permalink parser result
    92	 * @param permalinkRoom - Room in which the permalink is displayed.
    93	 * @returns Pill type or null if unable to determine.
    94	 */
    95	const determineType = (
    96	    forcedType: PillType | undefined,
    97	    parseResult: PermalinkParts | null,
    98	    permalinkRoom: Room | undefined,
    99	): PillType | null => {
   100	    if (forcedType) return forcedType;
   101	
   102	    if (parseResult?.roomIdOrAlias && parseResult?.eventId) {
   103	        if (parseResult.roomIdOrAlias === permalinkRoom?.roomId) {
   104	            return PillType.EventInSameRoom;
   105	        }
   106	
   107	        return PillType.EventInOtherRoom;
   108	    }
   109	
   110	    if (parseResult?.primaryEntityId) {
   111	        const prefix = parseResult.primaryEntityId[0] || "";
   112	        return (
   113	            {
   114	                "@": PillType.UserMention,
   115	                "#": PillType.RoomMention,
   116	                "!": PillType.RoomMention,
   117	            }[prefix] || null
   118	        );
   119	    }
   120	
   121	    return null;
   122	};
   123	
   124	/**
   125	 * Can be used to retrieve all information needed to display a permalink.
   126	 */
   127	export const usePermalink: (args: Args) => HookResult = ({
   128	    room: permalinkRoom,
   129	    type: forcedType,
   130	    url,
   131	}): HookResult => {
   132	    let resourceId: string | null = null;
   133	    let parseResult: PermalinkParts | null = null;
