   135	    if (url) {
   136	        parseResult = parsePermalink(url);
   137	
   138	        if (parseResult?.primaryEntityId) {
   139	            resourceId = parseResult.primaryEntityId;
   140	        }
   141	    }
   142	
   143	    const type = determineType(forcedType, parseResult, permalinkRoom);
   144	    const targetRoom = usePermalinkTargetRoom(type, parseResult, permalinkRoom);
   145	    const event = usePermalinkEvent(type, parseResult, targetRoom);
   146	    const member = usePermalinkMember(type, parseResult, targetRoom, event);
