   148	    let onClick: (e: ButtonEvent) => void = () => {};
   149	    let text = resourceId;
   150	
   151	    if (type === PillType.AtRoomMention && permalinkRoom) {
   152	        text = "@room";
   153	    } else if (type === PillType.UserMention && member) {
   154	        text = member.name || resourceId;
   155	        onClick = (e: ButtonEvent): void => {
   156	            e.preventDefault();
   157	            e.stopPropagation();
   158	            dis.dispatch({
   159	                action: Action.ViewUser,
   160	                member: member,
   161	            });
   162	        };
   163	    } else if (type === PillType.RoomMention) {
   164	        if (targetRoom) {
   165	            text = targetRoom.name || resourceId;
   166	        }
   167	    } else if (type === PillType.EventInSameRoom) {
   168	        text = member?.name || _t("User");
   169	    } else if (type === PillType.EventInOtherRoom) {
   170	        text = targetRoom?.name || _t("Room");
   171	    }
   172	
   173	    return {
   174	        event,
   175	        member,
   176	        onClick,
   177	        resourceId,
   178	        targetRoom,
   179	        text,
   180	        type,
   181	    };
   182	};
"
}

