    35	 */
    36	const determineUserId = (
    37	    type: PillType | null,
    38	    parseResult: PermalinkParts | null,
    39	    event: MatrixEvent | null,
    40	): string | null => {
    41	    if (type === null) return null;
    42	
    43	    if (parseResult?.userId) return parseResult.userId;
    44	
    45	    if (event && [PillType.EventInSameRoom, PillType.EventInOtherRoom].includes(type)) {
