    34	const determineInitialEvent = (
    35	    shouldLookUpEvent: boolean,
    36	    targetRoom: Room | null,
    37	    parseResult: PermalinkParts | null,
    38	): MatrixEvent | null => {
    39	    if (!shouldLookUpEvent || !targetRoom || !parseResult?.eventId) return null;
