    37	    type: PillType | null,
    38	    parseResult: PermalinkParts | null,
    39	    permalinkRoom: Room | undefined,
    40	): Room | null => {
    41	    if (type === PillType.AtRoomMention && permalinkRoom) return permalinkRoom;
