import { logger } from "matrix-js-sdk/src/logger";
import { IMatrixProfile } from "matrix-js-sdk/src/@types/search";
import { MatrixEvent, Room, RoomMember } from "matrix-js-sdk/src/matrix";
import { useContext, useEffect, useMemo, useState } from "react";

import { PillType } from "../components/views/elements/Pill";
import { MatrixClientPeg } from "../MatrixClientPeg";
import { PermalinkParts } from "../utils/permalinks/PermalinkConstructor";
import { SDKContext, SdkContextClass } from "../contexts/SDKContext";
import { UserProfilesStore } from "../stores/UserProfilesStore";

/**
 * Tries to determine the user Id of a permalink.
 * In case of a user permalink it is the user id.
 * In case of an event permalink it is the sender user Id of the event if that event is available.
 * Otherwise returns null.
 *
 * @param type - pill type
 * @param parseResult - permalink parse result
 * @param event - permalink event, if available
 * @returns permalink user Id. null if the Id cannot be determined.
 */
const determineUserId = (
    type: PillType | null,
    parseResult: PermalinkParts | null,
    event: MatrixEvent | null,
): string | null => {
    if (type === null) return null;

    if (parseResult?.userId) return parseResult.userId;

    if (event && [PillType.EventInSameRoom, PillType.EventInOtherRoom].includes(type)) {
        return event.getSender() ?? null;
    }

    return null;
};

const createRoomMemberFromProfile = (userId: string, profile: IMatrixProfile): RoomMember => {
    const member = new RoomMember("", userId);
    member.name = profile.displayname || userId;
    member.rawDisplayName = profile.displayname || userId;
    member.events.member = {
        getContent: () => {
            return { avatar_url: profile.avatar_url };
        },
        getDirectionalContent: function () {
            // eslint-disable-next-line
            return this.getContent();
        },
    } as MatrixEvent;
    return member;
};

/**
 * Get the UserProfilesStore from the SDK context if it is available, otherwise fall back to the
 * global SDK context. If neither has a client, undefined is returned so callers can use the
 * legacy profile lookup path.
 */
const useUserProfilesStore = (): UserProfilesStore | undefined => {
    const sdkContext = useContext(SDKContext);
    if (sdkContext?.client) {
        return sdkContext.userProfilesStore;
    }

    if (SdkContextClass.instance.client) {
        return SdkContextClass.instance.userProfilesStore;
    }

    return undefined;
};

/**
 * Hook to get the permalink member
 *
 * @param type - Permalink type
 * @param parseResult - Permalink parse result
 * @param targetRoom - Permalink target room {@link ./usePermalinkTargetRoom.ts}
 * @param event - Permalink event
 * @returns The permalink member:
 *          - The room member for a user mention
 *          - The sender for a permalink to an event in the same room
 *          - Null in other cases or the user cannot be loaded.
 */
export const usePermalinkMember = (
    type: PillType | null,
    parseResult: PermalinkParts | null,
    targetRoom: Room | null,
    event: MatrixEvent | null,
): RoomMember | null => {
    const userProfilesStore = useUserProfilesStore();
    // User mentions and permalinks to events in the same room require to know the user.
    // If it cannot be initially determined, it will be looked up later by a memo hook.
    const shouldLookUpUser = type && [PillType.UserMention, PillType.EventInSameRoom].includes(type);
    const userId = determineUserId(type, parseResult, event);
    const userInRoom = shouldLookUpUser && userId && targetRoom ? targetRoom.getMember(userId) : null;
    const knownProfile = useMemo(() => {
        if (!shouldLookUpUser || !userId || !userProfilesStore) {
            return undefined;
        }
        return userProfilesStore.getOnlyKnownProfile(userId);
    }, [shouldLookUpUser, userProfilesStore, userId]);
    const cachedMember = useMemo(() => {
        if (userInRoom) {
            return userInRoom;
        }
        if (!knownProfile || !userId) {
            return null;
        }
        return createRoomMemberFromProfile(userId, knownProfile);
    }, [knownProfile, userInRoom, userId]);
    const [member, setMember] = useState<RoomMember | null>(userInRoom ?? cachedMember);

    useEffect(() => {
        if (cachedMember) {
            setMember(cachedMember);
            return;
        }

        if (!shouldLookUpUser || !userId || member) {
            // nothing to do here
            return;
        }

        if (knownProfile === null) {
            // The profile is known to not exist.
            return;
        }

        if (userProfilesStore) {
            let cancelled = false;
            userProfilesStore
                .fetchOnlyKnownProfile(userId)
                .then((profile) => {
                    if (cancelled || !profile) {
                        return;
                    }
                    setMember(createRoomMemberFromProfile(userId, profile));
                })
                .catch((err) => {
                    logger.error("Could not retrieve profile data for " + userId + ":", err);
                });
            return () => {
                cancelled = true;
            };
        }

        // Legacy fallback for callers which do not have an SDK context with a client.
        const doProfileLookup = (userId: string): void => {
            MatrixClientPeg.get()
                .getProfileInfo(userId)
                .then((resp) => {
                    setMember(
                        createRoomMemberFromProfile(userId, {
                            displayname: resp.displayname,
                            avatar_url: resp.avatar_url,
                        }),
                    );
                })
                .catch((err) => {
                    logger.error("Could not retrieve profile data for " + userId + ":", err);
                });
        };

        doProfileLookup(userId);
    }, [cachedMember, knownProfile, member, shouldLookUpUser, userId, userProfilesStore]);

    return member;
};
