import { LruCache } from "../../src/utils/LruCache";

describe("LruCache temp", () => {
    it("throws for capacity below 1", () => {
        expect(() => new LruCache(0)).toThrow("Cache capacity must be at least 1");
        expect(() => new LruCache(-1)).toThrow("Cache capacity must be at least 1");
    });

    it("evicts least recently used and preserves insertion order", () => {
        const cache = new LruCache<string, number>(2);
        cache.set("a", 1);
        cache.set("b", 2);
        expect([...cache.values()]).toEqual([1, 2]);
        expect(cache.get("a")).toBe(1);
        expect([...cache.values()]).toEqual([1, 2]);
        cache.set("c", 3);
        expect([...cache.values()]).toEqual([1, 3]);
        expect(cache.get("b")).toBeUndefined();
    });

    it("handles deletes", () => {
        const cache = new LruCache<string, number>(5);
        cache.set("a", 1);
        cache.set("b", 2);
        cache.set("c", 3);
        cache.delete("missing");
        expect([...cache.values()]).toEqual([1, 2, 3]);
        cache.delete("b");
        expect([...cache.values()]).toEqual([1, 3]);
        cache.delete("a");
        cache.delete("c");
        expect([...cache.values()]).toEqual([]);
        cache.set("d", 4);
        expect([...cache.values()]).toEqual([4]);
    });

    it("updates recency but not value order", () => {
        const cache = new LruCache<string, number>(3);
        cache.set("a", 1);
        cache.set("b", 2);
        cache.set("c", 3);
        cache.set("a", 10);
        expect([...cache.values()]).toEqual([10, 2, 3]);
        cache.set("d", 4);
        expect([...cache.values()]).toEqual([10, 3, 4]);
    });
});
EOF
