import { logger } from "matrix-js-sdk/src/logger";
import { LruCache } from "../../src/utils/LruCache";

describe("LruCache full temp", () => {
    it("rejects capacity below 1", () => {
        expect(() => new LruCache(0)).toThrow("Cache capacity must be at least 1");
        expect(() => new LruCache(-1)).toThrow("Cache capacity must be at least 1");
    });

    it("marks has and get as recently used", () => {
        const cache = new LruCache<string, number>(2);
        cache.set("a", 1);
        cache.set("b", 2);
        expect(cache.has("a")).toBe(true);
        cache.set("c", 3);
        expect(cache.get("b")).toBeUndefined();
        expect([...cache.values()]).toEqual([1, 3]);

        const cache2 = new LruCache<string, number>(2);
        cache2.set("a", 1);
        cache2.set("b", 2);
        expect(cache2.get("a")).toBe(1);
        cache2.set("c", 3);
        expect(cache2.get("b")).toBeUndefined();
        expect([...cache2.values()]).toEqual([1, 3]);
    });

    it("keeps insertion order when updating or accessing", () => {
        const cache = new LruCache<string, number>(3);
        cache.set("a", 1);
        cache.set("b", 2);
        cache.set("c", 3);
        expect(cache.get("a")).toBe(1);
        expect([...cache.values()]).toEqual([1, 2, 3]);
        cache.set("b", 20);
        expect([...cache.values()]).toEqual([1, 20, 3]);
        cache.set("d", 4);
        expect([...cache.values()]).toEqual([1, 20, 4]);
    });

    it("handles deletes consistently", () => {
        const cache = new LruCache<string, number>(5);
        cache.set("a", 1);
        cache.set("b", 2);
        cache.set("c", 3);
        cache.delete("missing");
        cache.delete("b");
        expect([...cache.values()]).toEqual([1, 3]);
        cache.set("d", 4);
        cache.set("e", 5);
        cache.set("f", 6);
        expect([...cache.values()]).toEqual([1, 3, 4, 5, 6]);
        cache.clear();
        expect([...cache.values()]).toEqual([]);
        cache.set("g", 7);
        expect([...cache.values()]).toEqual([7]);
    });

    it("uses Map.prototype.set with the key and value", () => {
        const spy = jest.spyOn(Map.prototype, "set");
        const cache = new LruCache<string, number>(2);
        cache.set("a", 1);
        expect(spy).toHaveBeenCalledWith("a", 1);
        spy.mockRestore();
    });

    it("logs, clears, and swallows set errors", () => {
        const warn = jest.spyOn(logger, "warn").mockImplementation(() => {});
        const error = new Error("boom");
        const set = jest.spyOn(Map.prototype, "set").mockImplementationOnce(() => {
            throw error;
        });
        const cache = new LruCache<string, number>(2);
        cache.set("a", 1);
        cache.set("b", 2);
        expect(() => cache.set("c", 3)).not.toThrow();
        expect([...cache.values()]).toEqual([]);
        expect(warn).toHaveBeenCalledWith("LruCache error", error);
        set.mockRestore();
        warn.mockRestore();
    });
});
EOF
