        client.emit(RoomMemberEvent.Membership, {} as MatrixEvent, member);
        expect(store.getOnlyKnownProfile(userId)).toEqual({ displayname: "Alice", avatar_url: "mxc://alice" });
        const changedName = { ...member, rawDisplayName: "Bob" } as RoomMember;
        client.emit(RoomMemberEvent.Membership, {} as MatrixEvent, changedName);
        expect(store.getProfile(userId)).toBeUndefined();
        expect(store.getOnlyKnownProfile(userId)).toBeUndefined();
    });

    it("no longer known returns undefined despite cache", async () => {
        await store.fetchOnlyKnownProfile(userId);
        client.getRooms = jest.fn().mockReturnValue([]);
        expect(store.getOnlyKnownProfile(userId)).toBeUndefined();
        await expect(store.fetchOnlyKnownProfile(userId)).resolves.toBeUndefined();
        expect(client.getProfileInfo).toHaveBeenCalledTimes(1);
    });
});
